diff --git a/src/tests/chat.service.test.ts b/src/tests/chat.service.test.ts
new file mode 100644
index 0000000..f1f6bcc
--- /dev/null
+++ b/src/tests/chat.service.test.ts
@@ -0,0 +1,28 @@
+const create = jest.fn();
+jest.mock("openai", () => ({
+  __esModule: true,
+  default: jest.fn().mockImplementation(() => ({
+    chat: { completions: { create } },
+  })),
+}));
+jest.mock("./../common/kafka/node.kafka.service", () => ({
+  creatServiceCustomer: jest.fn(),
+  sendSingleMessage: jest.fn(),
+}));
+
+process.env.OPENAI_API_KEY = "placeholder";
+
+import { generateText } from "./../openai-chat/src/service/chat.service";
+
+test("generateText uses gpt-5.6-terra via chat completions", async () => {
+  create.mockResolvedValue({ choices: [{ message: { content: "hi" } }] });
+  const out = await generateText("hello");
+  expect(out).toBe("hi");
+  const body = create.mock.calls[0][0];
+  expect(body.model).toBe("gpt-5.6-terra");
+  expect(body.messages).toEqual([{ role: "user", content: "hello" }]);
+  expect(body.max_completion_tokens).toBeDefined();
+  expect(body.max_tokens).toBeUndefined();
+  expect(body.temperature).toBeUndefined();
+  expect(body.prompt).toBeUndefined();
+});
